const state={model:null,reservoir:null,rate:1.2,duration:20,year:12,percentile:50,layer:"pressure",limit:25,selectedIndex:null};
const $=id=>document.getElementById(id);
const els={reservoir:$('reservoirSelect'),rate:$('rateInput'),duration:$('durationInput'),year:$('yearInput'),limit:$('limitInput'),map:$('pressureMap'),chart:$('pressureChart'),tooltip:$('mapTooltip')};
const palettes={pressure:['#263344','#657ca5','#c27355','#f0ce6b'],margin:['#d05f55','#d5a85d','#9aaa75','#5d9f99'],geothermal:['#273945','#47777e','#62aaa7','#b8ddd0'],co2:['#202936','#315b6e','#62aaa7','#d7cf7a']};

function hexRgb(hex){const v=hex.replace('#','');return [0,2,4].map(i=>parseInt(v.slice(i,i+2),16))}
function colour(palette,t){t=Math.max(0,Math.min(.999,t));const n=t*(palette.length-1),i=Math.floor(n),f=n-i,a=hexRgb(palette[i]),b=hexRgb(palette[i+1]);return `rgb(${a.map((x,j)=>Math.round(x+(b[j]-x)*f)).join(',')})`}
function fmt(value,digits=1){return Number(value).toLocaleString('en-GB',{minimumFractionDigits:digits,maximumFractionDigits:digits})}
function nearestTimeIndex(year){const ts=state.model.times_years;let best=0;ts.forEach((v,i)=>{if(Math.abs(v-year)<Math.abs(ts[best]-year))best=i});return best}
function pressureAt(point,year=state.year){const ti=nearestTimeIndex(Math.min(year,state.duration)),pi={10:0,50:1,90:2}[state.percentile],base=point.pressure_bar[ti][pi]*state.rate;return year<=state.duration?base:base*Math.sqrt(state.duration/year)}
function co2At(point){if(!point.co2_saturation)return 0;const ti=nearestTimeIndex(Math.min(state.year,state.duration)),pi={10:0,50:1,90:2}[state.percentile];return Math.min(100,point.co2_saturation[ti][pi]*state.rate)}
function valueAt(point){const pressure=pressureAt(point),margin=Math.max(0,state.limit-pressure);if(state.layer==='pressure')return pressure;if(state.layer==='margin')return margin;if(state.layer==='co2')return co2At(point);return Math.min(100,pressure/state.limit*22)}
function ranges(){if(state.layer==='pressure'||state.layer==='margin')return [0,state.limit];if(state.layer==='co2')return [0,80];return [0,25]}

function populateReservoirs(){els.reservoir.innerHTML=state.model.reservoirs.filter(r=>r.assessment_type==='deep_geothermal').map(r=>`<option value="${r.id}">${r.name}</option>`).join('');els.reservoir.value='gassum';selectReservoir('gassum')}
function selectReservoir(id){state.reservoir=state.model.reservoirs.find(r=>r.id===id)||state.model.reservoirs[0];const points=state.reservoir.points,minLon=Math.min(...points.map(p=>p.lon)),maxLon=Math.max(...points.map(p=>p.lon)),minLat=Math.min(...points.map(p=>p.lat)),maxLat=Math.max(...points.map(p=>p.lat)),target={lon:minLon+(maxLon-minLon)*.7,lat:minLat+(maxLat-minLat)*.58};state.selectedIndex=points.reduce((best,p,i)=>((p.lon-target.lon)**2+(p.lat-target.lat)**2)<((points[best].lon-target.lon)**2+(points[best].lat-target.lat)**2)?i:best,0);$('reservoirSubtitle').textContent=`${state.reservoir.name} · regional screening grid`;$('engineLabel').textContent=state.reservoir.is_opm_result?`OPM Flow 2026.04 · ${state.reservoir.ensemble_size}-case ensemble`:`${state.reservoir.ensemble_size}-member analytical proxy`;$('provenance').textContent=`${state.model.model_version} · ${state.reservoir.is_opm_result?'OPM CO2STORE':'proxy'}`;render()}

function project(point,bounds,w,h){const pad=34,x=pad+(point.lon-bounds.minLon)/(bounds.maxLon-bounds.minLon)*(w-pad*2),y=h-pad-(point.lat-bounds.minLat)/(bounds.maxLat-bounds.minLat)*(h-pad*2);return{x,y}}
function mapGeometry(){const points=state.reservoir.points,b={minLon:Math.min(...points.map(p=>p.lon)),maxLon:Math.max(...points.map(p=>p.lon)),minLat:Math.min(...points.map(p=>p.lat)),maxLat:Math.max(...points.map(p=>p.lat))};return{bounds:b,w:900,h:650}}
function renderMap(){const {bounds,w,h}=mapGeometry(),points=state.reservoir.points,[lo,hi]=ranges(),palette=palettes[state.layer];els.map.setAttribute('viewBox',`0 0 ${w} ${h}`);const xs=[...new Set(points.slice(0,50).map(p=>p.lon))];const cell=Math.max(5,Math.min(16,(w-68)/Math.sqrt(points.length)*1.55));let svg=`<defs><pattern id="minorGrid" width="36" height="36" patternUnits="userSpaceOnUse"><path d="M36 0H0V36" fill="none" stroke="#526171" stroke-opacity=".12"/></pattern></defs><rect width="${w}" height="${h}" fill="#171d25"/><rect width="${w}" height="${h}" fill="url(#minorGrid)"/>`;
  svg+=`<path class="fault-path" d="M130 70C250 180 310 230 350 340S510 500 650 610"/>`;
  points.forEach((p,i)=>{const s=project(p,bounds,w,h),v=valueAt(p),t=(v-lo)/Math.max(hi-lo,.001),selected=i===state.selectedIndex;svg+=`<rect class="model-cell" data-index="${i}" x="${(s.x-cell/2).toFixed(1)}" y="${(s.y-cell/2).toFixed(1)}" width="${cell.toFixed(1)}" height="${cell.toFixed(1)}" rx="1" fill="${colour(palette,t)}" opacity="${state.layer==='margin'?'.88':'.82'}"/>`;if(selected)svg+=`<circle class="selected-ring" cx="${s.x.toFixed(1)}" cy="${s.y.toFixed(1)}" r="10"/>`});
  const injector=project(state.reservoir.reference_injector,bounds,w,h);svg+=`<g class="project-marker storage" transform="translate(${injector.x} ${injector.y})"><circle r="10"/><path d="M0-17V12M-6-8H6"/><text x="15" y="-8">Storage Alpha</text><text x="15" y="8">${state.rate.toFixed(1)} Mt/yr</text></g>`;
  const geoA=project({lon:bounds.minLon+(bounds.maxLon-bounds.minLon)*.7,lat:bounds.minLat+(bounds.maxLat-bounds.minLat)*.58},bounds,w,h),geoB=project({lon:bounds.minLon+(bounds.maxLon-bounds.minLon)*.34,lat:bounds.minLat+(bounds.maxLat-bounds.minLat)*.3},bounds,w,h);svg+=`<g class="project-marker geothermal" transform="translate(${geoA.x} ${geoA.y})"><circle r="9"/><path d="M-4 4L0-6 4 4M-3 1H3"/><text x="14" y="4">GeoHeat North</text></g><g class="project-marker geothermal" transform="translate(${geoB.x} ${geoB.y})"><circle r="9"/><path d="M-4 4L0-6 4 4M-3 1H3"/><text x="14" y="4">GeoHeat South</text></g>`;els.map.innerHTML=svg;
  els.map.querySelectorAll('.model-cell').forEach(cellEl=>{cellEl.addEventListener('click',()=>{state.selectedIndex=Number(cellEl.dataset.index);render()});cellEl.addEventListener('pointerenter',e=>showTooltip(e,Number(cellEl.dataset.index)));cellEl.addEventListener('pointerleave',()=>els.tooltip.hidden=true)});}
function showTooltip(event,index){const p=state.reservoir.points[index],v=pressureAt(p),headline=state.layer==='co2'?`${fmt(co2At(p))}% CO₂ saturation · P${state.percentile}`:`${fmt(v)} bar Δp · P${state.percentile}`;els.tooltip.innerHTML=`<strong>${headline}</strong><span>${fmt(p.depth_m,0)} m depth · ${fmt(p.permeability_md,0)} mD</span>`;els.tooltip.hidden=false;const canvas=document.querySelector('.map-canvas').getBoundingClientRect();els.tooltip.style.left=`${Math.min(canvas.width-205,event.clientX-canvas.left+12)}px`;els.tooltip.style.top=`${Math.max(65,event.clientY-canvas.top-12)}px`}

function renderDetail(){const p=state.reservoir.points[state.selectedIndex],pressure=pressureAt(p),margin=state.limit-pressure,use=Math.max(0,pressure/state.limit*100),maxRate=state.rate*state.limit/Math.max(pressure,.01);$('selectedName').textContent=`Cell ${state.selectedIndex+1}`;$('budgetValue').textContent=`${fmt(use,0)}%`;$('budgetBar').style.width=`${Math.min(100,use)}%`;$('budgetBar').style.background=use>100?'#d26055':use>75?'#d09e58':'#dec16b';$('budgetCaption').textContent=use>100?'Configured pressure constraint exceeded in this screening case.':`${fmt(Math.max(0,100-use),0)}% of the configured pressure headroom remains.`;$('pressureValue').textContent=`+${fmt(pressure)} bar`;$('pressureContext').textContent=`P${state.percentile} · year ${state.year}`;$('marginValue').textContent=`${margin>=0?'+':'−'}${fmt(Math.abs(margin))} bar`;$('injectionCost').textContent=`+${fmt(pressure*.78,0)}%`;$('productionCost').textContent=`−${fmt(pressure*.41,0)}%`;$('maxRate').textContent=`${fmt(Math.min(9.9,maxRate))} Mt/yr`;$('bindingConstraint').textContent=use>78?'Pressure headroom':'Geothermal receptor';$('envelopeTitle').textContent=use>100?'Scenario exceeds the configured screening envelope':use>78?'Scenario approaches a binding constraint':'Scenario remains inside the screening envelope';$('envelopeText').textContent=use>78?'Reduce rate, shorten duration, or run a calibrated OPM case to resolve the constraint.':'The indicated headroom is provisional and excludes calibrated geomechanics.';renderChart(p)}
function renderChart(p){const w=320,h=165,left=34,right=10,top=12,bottom=25,years=[1,5,10,20,30,40,50,60],values=years.map(y=>pressureAt(p,y)),max=Math.max(state.limit,...values)*1.12,x=y=>left+(y/60)*(w-left-right),y=v=>top+(1-v/max)*(h-top-bottom);let svg='';[0,.5,1].forEach(f=>{const yy=top+f*(h-top-bottom),val=max*(1-f);svg+=`<line class="chart-grid" x1="${left}" y1="${yy}" x2="${w-right}" y2="${yy}"/><text class="chart-axis" x="2" y="${yy+3}">${fmt(val,0)}</text>`});svg+=`<line class="chart-limit" x1="${left}" y1="${y(state.limit)}" x2="${w-right}" y2="${y(state.limit)}"/><text class="chart-axis" x="${w-55}" y="${y(state.limit)-4}">limit</text>`;const line=years.map((yr,i)=>`${i?'L':'M'}${x(yr).toFixed(1)} ${y(values[i]).toFixed(1)}`).join('');svg+=`<path class="chart-area" d="${line}L${x(60)} ${h-bottom}L${left} ${h-bottom}Z"/><path class="chart-line" d="${line}"/>`;years.forEach((yr,i)=>svg+=`<circle class="chart-point" cx="${x(yr)}" cy="${y(values[i])}" r="3"/>`);[0,20,40,60].forEach(yr=>svg+=`<text class="chart-axis" x="${x(yr)-5}" y="${h-7}">${yr}</text>`);svg+=`<text class="chart-axis" x="${w-30}" y="${h-7}">year</text>`;els.chart.innerHTML=svg;$('chartPercentile').textContent=`P${state.percentile}`}
function renderLegend(){const [lo,hi]=ranges(),labels={pressure:['Δp · bar','Pressure change'],margin:['Remaining · bar','Pressure margin'],geothermal:['Cost impact · %','Geothermal injection impact'],co2:['Gas saturation · %','CO₂ plume saturation']}[state.layer];$('legendLow').textContent=fmt(lo,0);$('legendHigh').textContent=fmt(hi,0);$('legendUnit').textContent=labels[0];$('legendRamp').style.background=`linear-gradient(90deg,${palettes[state.layer].join(',')})`;$('legendCaption').textContent=`P${state.percentile} · ${state.reservoir.is_opm_result?'OPM Flow ensemble':'analytical proxy'}`;$('mapTitle').textContent=`${labels[1]} · Year ${state.year}`}
function render(){if(!state.reservoir)return;$('rateOutput').textContent=`${state.rate.toFixed(1)} Mt/yr`;$('durationOutput').textContent=`${state.duration} yr`;$('yearOutput').textContent=`Year ${state.year}`;renderLegend();renderMap();renderDetail()}

els.reservoir.addEventListener('change',e=>selectReservoir(e.target.value));els.rate.addEventListener('input',e=>{state.rate=Number(e.target.value);render()});els.duration.addEventListener('input',e=>{state.duration=Number(e.target.value);render()});els.year.addEventListener('input',e=>{state.year=Number(e.target.value);render()});els.limit.addEventListener('change',e=>{state.limit=Math.max(1,Number(e.target.value));render()});document.querySelectorAll('.layer-button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.layer-button').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.layer=b.dataset.layer;render()}));document.querySelectorAll('.percentiles button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.percentiles button').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.percentile=Number(b.dataset.p);render()}));$('evaluateButton').addEventListener('click',()=>{render();$('evaluateButton').textContent='Scenario evaluated';setTimeout(()=>$('evaluateButton').textContent='Evaluate scenario',1200)});$('fitButton').addEventListener('click',()=>renderMap());$('aboutButton').addEventListener('click',()=>$('aboutDialog').showModal());$('searchInput').addEventListener('input',e=>{const q=e.target.value.toLowerCase();if(q.includes('north'))state.selectedIndex=Math.floor(state.reservoir.points.length*.7);else if(q.includes('south'))state.selectedIndex=Math.floor(state.reservoir.points.length*.3);else if(/^\d+$/.test(q)){state.selectedIndex=Math.min(state.reservoir.points.length-1,Math.max(0,Number(q)-1))}render()});

fetch('data/pressure-model.json').then(r=>{if(!r.ok)throw new Error('Dataset failed to load');return r.json()}).then(model=>{state.model=model;populateReservoirs()}).catch(error=>{$('engineLabel').textContent='Model unavailable';document.querySelector('.map-canvas').innerHTML=`<p style="padding:2rem;color:#d98b76">${error.message}</p>`});
